#include <stdio.h>

int main(void) {
    int N;
    scanf("%d", &N);

    int count1 = 0, count2 = 0;
    for (int i = 0; i < N; i++) {
        int t;
        scanf("%d", &t);
        if (t == 1) count1++;
        else count2++;
    }

    int P, M;
    scanf("%d", &P);
    scanf("%d", &M);

    if (count1 <= P && count2 <= M) {
        printf("S\n");
    } else {
        printf("N\n");
    }

    return 0;
}
